SELECT sm.id AS master_id,sm.title,sm.track,sm.disc,sm.album_id,a.name AS album_name FROM song_masters sm JOIN albums a ON a.id=sm.album_id WHERE sm.album_id!='pending-uploads' AND lower(trim(sm.title)) IN ('午夜emo时刻','华灯初上','双子座','双星系统','双鱼座','口口口-口口口，口口','只是喜欢这个身体吗','吴晴与钟诚','吴晴与钟诚·伴奏','和你一起','喜欢你的时间','喜气开场-乙巳新春','四千三百次的回答','四季共舞','回忆与旅途','因你而存在的故事','因你而铭记的旋律','境界、梦归长夏(feat.银星)','壳','处女座','夏日，海边，柠檬气泡水','多情岸','大人的答案','大航海家','天亮之后','天地审判官','天星问','天生偶像','天秤座','天蝎座','失乐园','失去理智','失宠的无声者','失心','失恋特工队') ORDER BY sm.title,sm.album_id